"""GIN reproduction vs the authors' published GIN rows (reports/primary/GIN-*.csv, commit f0ec556): agreement counts, claims check, bridge check. Reuses expanded_v4/tierb_compare.py functions.
Published GIN random-split rows do not exist, so only scaffold is compared; random-split GIN is an extension (protocol section 1)."""
import sys, json, hashlib, shutil
from pathlib import Path
V8=Path(__file__).resolve().parent;V4=V8.parent/'expanded_v4';sys.path.insert(0,str(V4))
import numpy as np, pandas as pd
import tierb_compare as tc
tc.ROOT=V8;tc.PREFIX['GIN']='GIN'
REPO=V8.parent/'repos'/'MUBen'/'reports'/'primary';REF=V8/'references'/'primary';REF.mkdir(parents=True,exist_ok=True)
DS=['bace','bbbp','clintox','tox21','esol','freesolv','lipo','qm7'];sums=[]
for d in DS:
    shutil.copy2(REPO/f'GIN-{d}.csv',REF/f'GIN-{d}.csv');sums.append(f"{hashlib.sha256((REF/f'GIN-{d}.csv').read_bytes()).hexdigest()}  references/primary/GIN-{d}.csv")
(V8/'references'/'SHA256.txt').write_text('\n'.join(sums)+'\n')
(V8/'results').mkdir(exist_ok=True)
c=tc.compare('scaffold');c.to_csv(V8/'results'/'comparison_scaffold.csv',index=False)
n=tc.counts(c);tot=n.groupby(['backbone','split'])[['n','within_1sd','within_2sd']].sum().reset_index();cl=tc.claims(c);bm=tc.by_metric(c)
# bridge check (protocol section 5): authors' trainer vs our GIN Deterministic on ESOL and QM7 scaffold
br=pd.read_csv(V8/'bridge_authors_gin_metrics.csv');ours=pd.DataFrame(json.loads((V8/'results'/'GIN'/'scaffold'/d/'per_seed_metrics.json').read_text()) for d in ['esol','qm7'])
rows=[]
for d in ['esol','qm7']:
    o=pd.DataFrame(json.loads((V8/'results'/'GIN'/'scaffold'/d/'per_seed_metrics.json').read_text()));o=o[o.method=='Deterministic']
    for m in ['rmse','mae','nll','ce']:
        a=br[br.dataset==d][m].astype(float);b=o[m].astype(float);sd=max(a.std(ddof=0),b.std(ddof=0));diff=abs(a.mean()-b.mean())
        rows.append({'dataset':d,'metric':m,'authors_trainer':round(a.mean(),4),'ours':round(b.mean(),4),'abs_diff':round(diff,4),'max_seed_sd':round(sd,4),'ratio_diff_to_sd':round(diff/sd,2) if sd>0 else np.nan,'consistent_lt_2sd':bool(diff<2*sd)})
bridge=pd.DataFrame(rows);bridge.to_csv(V8/'results'/'bridge_check.csv',index=False)
fence=tc.fence
md=['# GIN reproduction summary (generated by gin_compare.py; do not edit by hand)','',
    'Agreement: |reproduced mean - published mean| <= k x published SD over rows with published SD > 0; scaffold only (no published GIN random-split rows); scaffold ensembles have no published SD.','',
    '## Totals','',fence(tot.to_string(index=False)),'','## Per dataset','',fence(n.to_string(index=False)),'','## Claims check (datasets where the claim holds)','',fence(cl.to_string()) if len(cl) else '(none)','',
    '## Agreement by metric (median z = (reproduced - published) / published SD)','',fence(bm.to_string(index=False)),'','## Bridge check against the authors\' trainer (protocol section 5; consistent if |diff| < 2 x the larger seed SD)','',fence(bridge.to_string(index=False)),'',
    '## Deviations and limits','','- Pipeline: our Tier-B framework with the authors\' GIN encoder (muben.model.gin: embedding + torch_geometric GIN jk=cat, global add pool) and featuriser; our output head, loss, loop, seeds (0/100/200), methods and metrics (n0067, n0068).',
    '- The authors\' QM7 split files hold 6,830 compounds, not the 7,160 of the paper\'s Table 4 (same files as Tier B).','- Random-split GIN results are an extension with no published target.',
    '- MC dropout: dropout layers active, no normalisation layers in the GIN stack (torch_geometric default); BBP and SGLD act on the output head only, as for the other backbones.']
(V8/'results'/'GIN_SUMMARY.md').write_text('\n'.join(md)+'\n');print(tot.to_string(index=False));print(bridge.to_string(index=False))
